from common import *
import shutil,sys
def main():
 assert not(E/'configs/protocol.json').exists()
 for d in ['configs','data/public','data/_private','data/features','data/sanitized','models','results','logs','figures','videos']:(E/d).mkdir(parents=True,exist_ok=True)
 sources=[RGB/'data/public/windows_v1.json',RGB/'data/public/paired_inputs_v1.npz',RGB/'data/_private/supervision.npz',STATE/'data/public/windows_full.json',STATE/'data/public/inputs_full.npz',STATE/'data/_private/supervision_full.npz',TEMP/'data/metadata.json',TEMP/'results/audit.json',TRAIN/'data/_private/evaluation_metadata.json',TRAIN/'data/_private/targets.npz',P/'src/wm_symbolic/physical_oracle.py',CAND/'reader_seed1.pt',RGB/'source/cache.py',RGB/'source/registry.py']
 windows=[];groups=[]
 for name,e,mf,xf,yf in [('success_chain',RGB,'windows_v1.json','paired_inputs_v1.npz','supervision.npz'),('state_conditions',STATE,'windows_full.json','inputs_full.npz','supervision_full.npz')]:
  mm=read(e/'data/public'/mf)
  for i,r in enumerate(mm):windows.append({k:r[k]for k in ['window_id','root_id','split','environment','public_frames','anchor_frame','history_frame_indices']}|{'source':name,'source_index':i,'feature_path':str(e/'data/features'/(r['window_id']+'.npz')),'condition':'macro_endpoint'})
  groups.append({'name':name,'count':len(mm),'inputs':str(e/'data/public'/xf),'supervision':str(e/'data/_private'/yf)})
 tm=read(TEMP/'data/metadata.json');audit={r['sample_id']:r for r in read(TEMP/'results/audit.json')['recovered_samples']}
 for r in tm:
  paths=audit[r['sample_id']]['temporal_inputs']['long_history'];assert len(paths)==4
  windows.append({'window_id':r['sample_id'],'root_id':r['origin_root_id'],'split':r['split'],'environment':r['environment'],'public_frames':paths,'anchor_frame':r['anchor_frame'],'history_frame_indices':[r['anchor_frame']-k for k in [63,42,21,0]],'source':'contact_hard_examples','condition':r['condition'],'target_color':r['target_color'],'labels_private':r['labels_private']})
 assert len(windows)==312
 splitroots={s:sorted({r['root_id']for r in windows if r['split']==s})for s in ['train','dev']};assert not set(splitroots['train'])&set(splitroots['dev'])
 save(E/'configs/windows_before_encoding.json',windows);save(E/'configs/reused_groups.json',groups)
 q={'created_utc':now(),'scope':'Fixed predicate library + trained query-conditioned relation reader + learned lifted action rules; inspired minimum, not full VisualPredicator reproduction.','no_cloud_no_install':True,'data':{'reader_windows':312,'train_windows':sum(r['split']=='train'for r in windows),'dev_windows':sum(r['split']=='dev'for r in windows),'train_roots':splitroots['train'],'dev_roots':splitroots['dev'],'training_AB_only':True,'development_C_only':True,'old_D_observations_used':False,'hard_examples':'54 existing causal windows: ordinary/support-contact negatives and held positives, re-encode with current RGB-only regions; all7 physical labels separately valid-masked.','rules':'132 AB transitions from36roots;42 C transitions from12roots; successful effects plus real failed/refused tuples for preconditions; never invent success effects for failures.'},'architecture':'From-scratch typed block/drawer/gripper96D nodes, shared query-conditioned edgeMLP/GRU64 and binary head; no colour ID, object index embedding, GT position/contact, phase, action or task text in perception. Drawer uses public static-grid context, gripper wrist-grid+15D proprio; not precise object segmentation for anchors.','query_templates':['Holding(object)','In(object,drawer)','Open(drawer)'],'history':'4 causal public frames at[-63,-42,-21,0],2.1s, no previous predicates/actions or occlusion memory module','training':{'seed':0,'updates':1200,'batch':32,'sampling':'uniform AB roots, uniform window within root; all7 queries perwindow; record indices','optimizer':'AdamW lr0.001 weight_decay0.001 clip1','loss':'mean across Holding/In/Open groups of valid binary cross entropy with AB-only inverse class weights','checkpoints':[300,600,900,1200],'selection':'minimum C root-macro group-balanced BCE, tie earlier; all1200 updates always run; no D selection; fixed threshold.5'},'rules':{'positive_effects':'exact before/after differences, normalized by action argument roles, cluster by skill and lifted add/delete sets','candidate_literals':['Holding(x)','In(x,drawer)','Open(drawer)','EmptyHand()','OtherHeld(x)'],'derived':'EmptyHand is forall blocks notHolding; OtherHeld exists non-target held. Definitions are supplied; inclusion in learned preconditions is learned.','negated_literals':True,'learner':'intersect positive pre-state literals; enumerate shortest conjunction excluding real same-skill failures and other effect clusters; accuracy minus0.001*literal_count explicit; if no exact separator preserve conflict and mark unsupported','predicate_invention':False,'all7_common_evaluation':True,'target_binding':'Lift explicit colour argument; Place binds x to unique currently held object (motor-skill convention), empty-grip negative has no bound x. No invented unexecuted object-action negatives.'},'test':{'new_roots':6,'balance':'3colours x initial drawer closed/open','arms':['visual_learned_rules','GT_symbols_learned_rules'],'goals':'closed-initial roots: In(target,drawer) and closed; open-initial roots: In(target,drawer) and In(nextcolour,drawer) and closed','max_calls_per_arm_root':8,'maximum_calls':96,'planner':'BFS depth8, expansion512, learned preconditions/effects only; re-read real endpoint and replan eachstep; stop on UNKNOWN, no plan, failed/refused controller, repeated symbolic state-action, or budget.','controller':'unchanged PhysicalOracle900 primitive controls+96 realhold each call; initial96hold; no intermediate resets or forced successes','extra_state_diagnostics':'after each executed macro, at most2 preregistered past windows: first closed-gripper descend anchor and lower_into_drawer firstframe+63 if available, only for perception scoring, never planning. No model adaptation.','freezing':'new root layouts and model/rule hashes frozen before any test physics; exclude all archived roots by ID/seed/layout; retain failures, no replacement','comparison':'GT symbols diagnostic uses same learned rules and controller. Fixed symbolic rules scored offline on same7facts. Old reader only a frozen perception baseline on same images.','acceptance':'report per-predicate positive/negative/UNKNOWN, full7 and roots; applicability vs real status, success-effect prediction; real task success including every assigned root. Running version is functional evidence, not reliability certification or original guide completion.'},'fixed_sha256':{str(p):sha(p)for p in sources}}
 save(E/'configs/protocol.json',q);(E/'configs/protocol.json').chmod(0o444);print(json.dumps({'windows':len(windows),'train_roots':len(splitroots['train']),'dev_roots':len(splitroots['dev']),'protocol_sha256':sha(E/'configs/protocol.json')},ensure_ascii=False))
if __name__=='__main__':main()
